using System;using System.IO;using System.Linq;using System.Security.Cryptography;using System.Text;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;
namespace IdleIntelligence.Tests {
 public sealed class AnalysisPlanningTests {
  static GameState Fund(){var s=Game.New(1000000);s.Data=ScientificNumber.From(1000000);s.Workshop.nodes=new[]{"F02","F03"};return s;}
  [Test]public void QueueIsUnpaidBoundedAndWaitsForResources(){var s=Fund();var original=JsonUtility.ToJson(StateData.From(s));for(int i=0;i<6;i++)s=MaterialAnalysis.Queue(s,0);Assert.That(s.Industry.analysisQueue.Length,Is.EqualTo(6));Assert.That(s.Data.ToDouble(),Is.EqualTo(1000000));Assert.That(MaterialAnalysis.Queue(s,0),Is.SameAs(s));Assert.That(MaterialAnalysis.Queue(Fund(),2).Industry.analysisQueue,Is.Empty);var poor=s.Copy();poor.Data=ScientificNumber.Zero;Assert.That(MaterialAnalysis.StartQueued(poor),Is.SameAs(poor));var started=MaterialAnalysis.StartQueued(s);Assert.That(started.Data.ToDouble(),Is.EqualTo(999750));Assert.That(started.Industry.analysisQueue.Length,Is.EqualTo(5));Assert.That(started.Workshop.analysis.units,Is.EqualTo(24));Assert.That(MaterialAnalysis.RemoveQueued(started,2).Industry.analysisQueue.Length,Is.EqualTo(4));Assert.That(Fund().Industry.analysisQueue,Is.Empty,original);}
  [Test]public void OfflineDrainsOnceAndRepeatRespectsReserve(){var s=Fund();for(int i=0;i<6;i++)s=MaterialAnalysis.Queue(s,0);var n=Game.Advance(s,s.SavedAt+3600000);Assert.That(n.Lifetime.analysesCompleted,Is.EqualTo(6));Assert.That(n.Industry.analysisQueue,Is.Empty);Assert.That(n.Workshop.hasAnalysis,Is.False);Assert.That(n.Industry.lastAnalysisAmounts.Sum(),Is.EqualTo(24));Assert.That(Game.Advance(n,n.SavedAt),Is.SameAs(n));var repeat=Fund();repeat.Meta.analysisAuto=true;repeat.Prestige.dataReserve=repeat.Data.ToData();Assert.That(MetaAutomation.Analysis(repeat),Is.SameAs(repeat));repeat.Prestige.dataReserve=ScientificNumber.Zero.ToData();Assert.That(MetaAutomation.Analysis(repeat).Workshop.hasAnalysis,Is.True);}
  [Test]public void OvernightStopsAtTheExistingEightHourLimit(){var s=Fund();s.Meta.analysisAuto=true;var eight=Game.Advance(s,s.SavedAt+28800000);var nine=Game.Advance(s,s.SavedAt+32400000);Assert.That(nine.Workshop.components,Is.EqualTo(eight.Workshop.components));Assert.That(nine.Data.CompareTo(eight.Data),Is.Zero);Assert.That(nine.Lifetime.analysesCompleted,Is.EqualTo(eight.Lifetime.analysesCompleted));Assert.That(nine.SavedAt,Is.EqualTo(s.SavedAt+32400000));}
  [Test]public void ExplicitWebImportRejectsChangedQueuesAndReceipts(){var json=File.ReadAllText(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/WebImportReferenceCase.json"));var t=JsonUtility.FromJson<WebTransfer>(json);Assert.That(UnityWebImport.Validate(json).Web.sourceVersion,Is.EqualTo(CompatibilityCatalog.WebSaveVersion));var codec=new UnitySaveCodec();var d=codec.Decode(t.payload);d.industry.analysisQueue=new[]{0};t.payload=codec.Encode(d);Assert.Throws<FormatException>(()=>UnityWebImport.Validate(JsonUtility.ToJson(t)));t=JsonUtility.FromJson<WebTransfer>(json);d=codec.Decode(t.payload);d.industry.lastAnalysisRecipe=0;d.industry.lastAnalysisAmounts[0]=5;t.payload=codec.Encode(d);Assert.Throws<FormatException>(()=>UnityWebImport.Validate(JsonUtility.ToJson(t)));}
  [Test]public void Schema23OriginalAndPaidYieldSurviveMigration(){string dir=Path.Combine(Path.GetTempPath(),"analysis-v23-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{var codec=new UnitySaveCodec();var s=MaterialAnalysis.Start(Fund(),0);s.Workshop.analysis.units=12;s.Workshop.inventory=new[]{new ItemInstance{id="kept",type="quantum-chip",level=13,rarity=3}};string payload=codec.Encode(StateData.From(s));payload=System.Text.RegularExpressions.Regex.Replace(payload,"\"analysisQueue\":\\[\\],","");payload=System.Text.RegularExpressions.Regex.Replace(payload,"\"lastAnalysisRecipe\":-1,","");payload=System.Text.RegularExpressions.Regex.Replace(payload,"\"lastAnalysisAmounts\":\\[[^\\]]*\\],","");string hash;using(var h=SHA256.Create())hash=BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(payload))).Replace("-","").ToLowerInvariant();string raw=codec.EncodeEnvelope(new SaveEnvelope{format=AtomicSaveStore.Format,version=23,payload=payload,sha256=hash}),path=Path.Combine(dir,"save.json");File.WriteAllText(path,raw);var store=new AtomicSaveStore(path,codec);var load=store.Load(s.SavedAt);Assert.That(load.Writable,Is.True,load.Message);Assert.That(File.ReadAllText(path),Is.EqualTo(raw));Assert.That(load.State.Workshop.inventory.Single().level,Is.EqualTo(13));Assert.That(load.State.Industry.analysisQueue,Is.Empty);Assert.That(load.State.Workshop.analysis.units,Is.EqualTo(12));var end=Game.Advance(load.State,s.SavedAt+600000);Assert.That(end.Industry.lastAnalysisAmounts.Sum(),Is.EqualTo(12));store.Save(end);Assert.That(codec.DecodeEnvelope(File.ReadAllText(path)).version,Is.EqualTo(AtomicSaveStore.Version));Assert.That(File.ReadAllText(path+".backup"),Is.EqualTo(raw));Assert.That(new AtomicSaveStore(path,codec).Load(end.SavedAt).State.Industry.lastAnalysisAmounts.Sum(),Is.EqualTo(12));}finally{Directory.Delete(dir,true);}}
 }
}
